const html = String(items[0].json);

// ---------------------
// Product Name
// ---------------------
let productName = null;

// Shopify JSON
let match =
  html.match(/"product_title"\s*:\s*"([^"]+)"/i) ||
  html.match(/"title"\s*:\s*"Airpods[^"]+"/i);

if (match) {
  productName = match[1] || match[0].replace(/"title"\s*:\s*"/, "").replace(/"$/, "");
}

// Product H1 fallback
if (!productName) {
  match = html.match(
    /<h1[^>]*class="[^"]*product__title[^"]*"[^>]*>(.*?)<\/h1>/is
  );

  if (match) {
    productName = match[1]
      .replace(/<[^>]*>/g, "")
      .replace(/\s+/g, " ")
      .trim();
  }
}

// ---------------------
// Price
// ---------------------
const priceMatch =
  html.match(/Rs\.\s*([\d,]+)/i);

const competitorPrice = priceMatch
  ? Number(priceMatch[1].replace(/,/g, ""))
  : null;

// ---------------------
// Stock
// ---------------------
const soldOut =
  /Sold out/i.test(html) ||
  /"available"\s*:\s*false/i.test(html) ||
  /inventory_quantity"\s*:\s*0/i.test(html);

return [
  {
    json: {
      productName,
      competitorPrice,
      stockStatus: soldOut ? "Out of Stock" : "In Stock",
    },
  },
];

const yourPrice = Number(
  $items("Get Competitor URL")[0].json["Your Price"]
);

const competitorPrice = Number($json.competitorPrice);
const stockStatus = ($json.stockStatus || "").toLowerCase();

const inStock = stockStatus === "in stock";

const undercut = competitorPrice < yourPrice && inStock;

const priceGap = Number((yourPrice - competitorPrice).toFixed(2));

const percentageDifference = Number(
  ((priceGap / yourPrice) * 100).toFixed(2)
);

return [
  {
    json: {
      ...$json,
      yourPrice,
      undercut,
      priceGap,
      percentageDifference,
      lastChecked: new Date().toISOString(),
    },
  },
];
